def max_sub_array_sum_repeated(arr, n, k):
    def kadane(array):
        """Standard Kadane's algorithm to find the max subarray sum."""
        max_current = max_global = array[0]
        for i in range(1, len(array)):
            max_current = max(array[i], max_current + array[i])
            max_global = max(max_global, max_current)
        return max_global

    # Case when k = 1: just run Kadane's on the original array
    if k == 1:
        return kadane(arr)

    # Sum of the original array
    total_sum = sum(arr)

    # Run Kadane's on the array repeated twice to capture wrapping cases
    max_sum_twice = kadane(arr * 2)

    if total_sum > 0:
        # If the total sum of the array is positive, we can use it for full repetitions
        return max_sum_twice + (k - 2) * total_sum
    else:
        # If not, the best sum will be within the twice-repeated array
        return max_sum_twice
