def max_aggregate(data):
    # Dictionary to store the aggregated scores
    aggregates = {}

    # Iterate through the list of tuples to aggregate scores
    for name, score in data:
        if name in aggregates:
            aggregates[name] += score
        else:
            aggregates[name] = score

    # Find the name with the maximum aggregate score
    max_name = max(aggregates, key=aggregates.get)
    return (max_name, aggregates[max_name])

