import math
from functools import lru_cache

def count_binary_seq(n):
    @lru_cache(None)
    def helper(pos, balance):
        # If we've processed all bits and balance is zero, it's a valid sequence
        if pos == 2 * n:
            return 1 if balance == 0 else 0

        # If the balance is out of range, this path is invalid
        if abs(balance) > n:
            return 0

        # Explore the sequence by adding a 0 or 1 to the current position
        # Adding a 0 decreases balance for the first n bits, increases for the last n bits
        # Adding a 1 increases balance for the first n bits, decreases for the last n bits
        if pos < n:  # First half
            return helper(pos + 1, balance + 1) + helper(pos + 1, balance - 1)
        else:  # Second half
            return helper(pos + 1, balance - 1) + helper(pos + 1, balance + 1)

    return helper(0, 0)

# Example usage and test
assert math.isclose(count_binary_seq(1), 2.0, rel_tol=0.001)
assert math.isclose(count_binary_seq(2), 6.0, rel_tol=0.001)
assert math.isclose(count_binary_seq(3), 20.0, rel_tol=0.001)
