def sumofFactors(n):
    def is_even(x):
        return x % 2 == 0

    even_factors_sum = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:  # Check if i is a factor
            if is_even(i):
                even_factors_sum += i
            # Check the corresponding pair factor (n // i) if it's different from i
            if i != n // i and is_even(n // i):
                even_factors_sum += n // i
    return even_factors_sum

# Example usage
assert sumofFactors(18) == 26
