def count_Substrings(s):
    def sum_of_digits(sub):
        return sum(int(c) for c in sub)

    count = 0
    n = len(s)

    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = s[i:j]
            if sum_of_digits(substring) == len(substring):
                count += 1

    return count

# Test example
assert count_Substrings('112112') == 6
