def move_num(input_string):
    letters = []
    numbers = []
    temp_num = ""

    for char in input_string:
        if char.isdigit():
            temp_num += char
        else:
            if temp_num:
                numbers.append(temp_num)
                temp_num = ""
            letters.append(char)

    if temp_num:
        numbers.append(temp_num)

    return "".join(letters) + "".join(numbers)

