def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into one. If there are duplicate keys,
    the value from the dictionary that appears last (in order: dict1 -> dict2 -> dict3) will overwrite earlier ones.
    """
    # Combine dictionaries using dictionary unpacking (**kwargs), ensuring the order of merging respects dict1 -> dict2 -> dict3
    merged_dict = {**dict1, **dict2, **dict3}
    return merged_dict

